import type { AmbientId } from "@/content/techniques/registry";

/**
 * Ambient beds are synthesized procedurally by FFmpeg (noise + filters + slow modulation).
 * They are generated by our own code, so there are no third-party licensing questions.
 * Licensed recordings can be added later by mapping an id to a stored file.
 */
export function ambientSource(id: AmbientId, durationSec: number): string | null {
  const d = Math.max(1, durationSec).toFixed(2);
  switch (id) {
    case "rain":
      return `anoisesrc=color=pink:amplitude=0.35:sample_rate=44100:duration=${d},highpass=f=350,lowpass=f=6500,volume='0.85+0.15*sin(2*PI*t/17)':eval=frame`;
    case "ocean":
      return `anoisesrc=color=brown:amplitude=0.6:sample_rate=44100:duration=${d},lowpass=f=900,volume='0.25+0.75*pow(0.5+0.5*sin(2*PI*t/9.5),2)':eval=frame`;
    case "wind":
      return `anoisesrc=color=pink:amplitude=0.4:sample_rate=44100:duration=${d},bandpass=f=550:width_type=h:w=500,volume='0.45+0.35*sin(2*PI*t/13)+0.2*sin(2*PI*t/5.3)':eval=frame`;
    case "night":
      return `anoisesrc=color=brown:amplitude=0.3:sample_rate=44100:duration=${d},lowpass=f=420,volume='0.8+0.2*sin(2*PI*t/23)':eval=frame`;
    case "soft_tones":
      return (
        `aevalsrc='0.22*sin(2*PI*110*t)*(0.6+0.4*sin(2*PI*t/11))` +
        `+0.16*sin(2*PI*164.81*t)*(0.55+0.45*sin(2*PI*t/7.3))` +
        `+0.10*sin(2*PI*220*t)*(0.5+0.5*sin(2*PI*t/13.7))` +
        `+0.06*sin(2*PI*329.63*t)*(0.5+0.5*sin(2*PI*t/17.1))':s=44100:d=${d},lowpass=f=1800,aecho=0.6:0.5:120|240:0.25|0.15`
      );
    case "none":
    default:
      return null;
  }
}

/** Ambient level relative to the voice (0–100 → linear gain). Kept low and ducked under speech. */
export function ambientGain(volumePercent: number): number {
  return Math.min(1, Math.max(0, volumePercent / 100)) * 0.55;
}
